(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.MartinsRdoRemoto=api;})(globalThis,()=>{'use strict';
const uuid=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(x);
function prepare(rdo,employees,mapping,company,revision=0){if(!uuid(company)||!uuid(mapping.works?.[rdo.obra]))throw Error('Vincule empresa e obra pelos UUIDs do Supabase');if(!rdo.id||!/^\d{4}-\d{2}-\d{2}$/.test(rdo.data)||!['Aprovado','Rascunho'].includes(rdo.status)||!Number.isSafeInteger(revision)||revision<0)throw Error('RDO ou revisão inválida');const seen=new Set(),workers=[];
for(const w of rdo.trabalhadores||[]){const matches=employees.filter(e=>w.funcionarioId?String(e.id)===String(w.funcionarioId):String(e.nome).trim().toLocaleLowerCase('pt-BR')===String(w.nome).trim().toLocaleLowerCase('pt-BR'));if(matches.length!==1)throw Error('Vínculo local ambíguo ou ausente: '+w.nome);const id=mapping.employees?.[matches[0].id],h=Number(w.horas);if(!uuid(id)||!Number.isFinite(h)||h<=0||h>8||seen.has(id))throw Error('UUID, horas ou profissional repetido: '+w.nome);seen.add(id);workers.push({funcionario_id:id,horas:h});}
return {p_empresa:company,p_id_local:String(rdo.id),p_obra:mapping.works[rdo.obra],p_data:rdo.data,p_conteudo:structuredClone(rdo),p_trabalhadores:workers,p_revisao_esperada:revision};}
async function send(client,args){const result=await client.rpc('martins_salvar_rdo_integrado',args);if(result.error)throw result.error;if(!uuid(result.data?.id)||!Number.isSafeInteger(result.data?.revisao)||result.data.revisao<1)throw Error('Resposta não confirmada; consulte o documento remoto antes de repetir');return result.data;}
return {uuid,prepare,send};});
